import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("How many tickets? ");
        String typed = scanner.nextLine();      // text, even if it is digits
        int tickets = Integer.parseInt(typed);  // now a real number

        System.out.println("That will be " + (tickets * 250) + " rupees.");
    }
}

